answerCalls.rawCandidateText:
{
  "directAnswer": "Whether a service provided overseas is zero-rated or out-of-scope depends on the specific nature of the service and where it is performed or consumed. Under Singapore GST law, simply providing a service to an overseas customer does not automatically make it zero-rated; it must fall within the specific categories of international services under Section 21(3) of the GST Act. Services that do not fall within the scope of taxable supplies in Singapore (such as certain services performed entirely outside Singapore by an overseas branch or where no taxable nexus exists) may be treated as out-of-scope.",
  "keyRules": [
    "Section 21(3) of the GST Act sets out the qualifying criteria for zero-rating international services, requiring each service to meet specific statutory descriptions and conditions rather than relying solely on the customer's overseas status.",
    "Under Section 11 of the GST Act, the time of supply is determined by the earlier of the issuance of an invoice or the receipt of payment."
  ],
  "caveats": [
    "An overseas customer alone is insufficient to qualify a service for zero-rating under Section 21(3).",
    "Specific documentary evidence must be maintained to substantiate zero-rated or out-of-scope treatment as required by IRAS guidelines."
  ],
  "statuteReferences": [
    {
      "standard": "Goods and Services Tax Act 1993",
      "paragraph": "Section 21(3)",
      "authority": "IRAS",
      "officialSourceUrl": "https://sso.agc.gov.sg/Act/GSTA1993?ProvIds=P15-#pr21-"
    },
    {
      "standard": "Goods and Services Tax Act 1993",
      "paragraph": "Section 11",
      "authority": "IRAS",
      "officialSourceUrl": "https://sso.agc.gov.sg/Act/GSTA1993?ProvIds=P13-#pr11-"
    }
  ]
}

